import 'package:equatable/equatable.dart';

/// Base class for domain-level events emitted by the conversational chat stream.
sealed class ChatStreamEvent extends Equatable {
  const ChatStreamEvent();
}

/// Emitted incrementally as conversational AI tokens arrive.
class ChatTokenEvent extends ChatStreamEvent {
  const ChatTokenEvent({required this.text});

  /// The partial text fragment generated by the AI model.
  final String text;

  @override
  List<Object?> get props => [text];
}

/// Emitted when the AI identifies and creates a new Learning Goal.
class ChatGoalCreatedEvent extends ChatStreamEvent {
  const ChatGoalCreatedEvent({required this.goalId});

  /// The unique UUID of the newly generated Learning Goal.
  final String goalId;

  @override
  List<Object?> get props => [goalId];
}

/// Emitted when roadmap generation begins.
class ChatRoadmapStartedEvent extends ChatStreamEvent {
  const ChatRoadmapStartedEvent({required this.learningGoalId});

  /// The Learning Goal ID for which the roadmap is being synthesized.
  final String learningGoalId;

  @override
  List<Object?> get props => [learningGoalId];
}

/// Emitted when roadmap synthesis and topic persistence complete.
class ChatRoadmapCompletedEvent extends ChatStreamEvent {
  const ChatRoadmapCompletedEvent({required this.roadmapId});

  /// The unique UUID of the generated Roadmap.
  final String roadmapId;

  @override
  List<Object?> get props => [roadmapId];
}

/// Emitted as the terminal success event when generation completes.
class ChatCompleteEvent extends ChatStreamEvent {
  const ChatCompleteEvent({this.message = 'Generation completed'});

  /// Completion message provided by the server.
  final String message;

  @override
  List<Object?> get props => [message];
}

/// Emitted when the backend reports an AI generation or execution error.
class ChatErrorEvent extends ChatStreamEvent {
  const ChatErrorEvent({required this.message});

  /// Error description sent by the server.
  final String message;

  @override
  List<Object?> get props => [message];
}

/// Preserves unrecognized or future backend events without breaking the client.
class ChatUnknownEvent extends ChatStreamEvent {
  const ChatUnknownEvent({
    required this.eventName,
    required this.rawPayload,
    this.data,
  });

  /// The original event name string received from the server.
  final String eventName;

  /// The raw payload string.
  final String rawPayload;

  /// Decoded JSON payload if parseable, or null.
  final dynamic data;

  @override
  List<Object?> get props => [eventName, rawPayload, data];
}
